<script>
(function () {
  var root = document.querySelector('.app');
  var statusEl = document.getElementById('status');

  var defaults = {
    theme: 'system', language: 'en', compact: false,
    notify: true, sound: false, digest: 'daily',
    cache: 256, timeout: 30, telemetry: false
  };
  var state = Object.assign({}, defaults);

  // Tabs
  var tabs = root.querySelectorAll('.tab');
  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      tabs.forEach(function (t) { t.classList.remove('active'); t.setAttribute('aria-selected', 'false'); });
      tab.classList.add('active');
      tab.setAttribute('aria-selected', 'true');
      root.querySelectorAll('.page').forEach(function (p) { p.classList.remove('active'); });
      document.getElementById('page-' + tab.dataset.page).classList.add('active');
    });
  });

  // Segmented controls
  root.querySelectorAll('.seg').forEach(function (seg) {
    var key = seg.dataset.key;
    seg.querySelectorAll('button').forEach(function (b) {
      b.addEventListener('click', function () {
        seg.querySelectorAll('button').forEach(function (x) { x.classList.remove('active'); });
        b.classList.add('active');
        state[key] = b.dataset.val;
        dirty();
      });
    });
  });

  // Inputs
  root.querySelectorAll('input[data-key], select[data-key]').forEach(function (el) {
    var key = el.dataset.key;
    var evt = (el.type === 'range' || el.type === 'number' || el.type === 'text') ? 'input' : 'change';
    el.addEventListener(evt, function () {
      if (el.type === 'checkbox') state[key] = el.checked;
      else if (el.type === 'range' || el.type === 'number') state[key] = Number(el.value);
      else state[key] = el.value;
      if (key === 'cache') document.getElementById('cacheVal').textContent = el.value + ' MB';
      dirty();
    });
  });

  function dirty() {
    statusEl.textContent = 'Unsaved changes';
    statusEl.classList.remove('saved');
  }

  document.getElementById('save').addEventListener('click', function () {
    statusEl.textContent = '\u2713 Settings saved';
    statusEl.classList.add('saved');
    // Bridge back to the MCP host if available.
    try {
      if (window.parent) {
        window.parent.postMessage({ type: 'settings.save', payload: state }, '*');
      }
    } catch (e) {}
  });

  document.getElementById('reset').addEventListener('click', function () {
    state = Object.assign({}, defaults);
    // reflect defaults in UI
    root.querySelectorAll('input[data-key], select[data-key]').forEach(function (el) {
      var k = el.dataset.key;
      if (el.type === 'checkbox') el.checked = defaults[k];
      else el.value = defaults[k];
    });
    root.querySelectorAll('.seg').forEach(function (seg) {
      var k = seg.dataset.key;
      seg.querySelectorAll('button').forEach(function (b) {
        b.classList.toggle('active', b.dataset.val === defaults[k]);
      });
    });
    document.getElementById('cacheVal').textContent = defaults.cache + ' MB';
    statusEl.textContent = 'Reset to defaults';
    statusEl.classList.remove('saved');
  });
})();
</script>
